The code statements that fix the bug are:
if (stream->prepare_write) {
	stream->prepare_write(subreq);
	__set_bit(NETFS_SREQ_IN_PROGRESS, &subreq->flags);
	netfs_stat(&netfs_n_wh_retry_write_subreq);
